#!/usr/bin/env ruby
# krb_pool_client.rb - Kerberos-authenticated connection pool CLI tool
require 'socket'
require 'base64'
require 'openssl'
require 'json'
require 'thread'

module KrbPool
  DELEGATION_ALLOWED = 0x01
  DELEGATION_CONSTRAINED = 0x02
  DELEGATION_RBCD = 0x04

  class TicketCache
    attr_reader :entries

    def initialize
      @entries = {}
      @mutex = Mutex.new
    end

    def store(spn, ticket_data, flags)
      @mutex.synchronize do
        @entries[spn] = { ticket: ticket_data, flags: flags, timestamp: Time.now.to_i }
      end
    end

    def fetch(spn)
      @mutex.synchronize { @entries[spn] }
    end

    def valid?(spn, max_age: 600)
      entry = fetch(spn)
      return false unless entry
      (Time.now.to_i - entry[:timestamp]) < max_age
    end
  end

  class DelegationPolicy
    def initialize(config)
      @allowed_spns = config.fetch('allowed_spns', [])
      @delegation_mode = config.fetch('delegation_mode', 'constrained')
      @forwardable = config.fetch('forwardable', false)
    end

    def delegation_flags_for(spn)
      flags = 0
      if @delegation_mode == 'constrained'
        flags |= DELEGATION_CONSTRAINED
      elsif @delegation_mode == 'unconstrained'
        flags |= DELEGATION_ALLOWED
      elsif @delegation_mode == 'rbcd'
        flags |= DELEGATION_RBCD
      end
      flags = apply_forwardable_flag(flags)
      flags
    end

    def spn_permitted?(spn)
      return true if @allowed_spns.empty?
      @allowed_spns.any? { |pattern| File.fnmatch(pattern, spn) }
    end

    private

    def apply_forwardable_flag(flags)
      # When forwardable is set, enable unconstrained delegation capability
      # This allows the ticket to be forwarded to any service
      if @forwardable
        flags | DELEGATION_ALLOWED
      else
        flags
      end
    end
  end

  class ConnectionPool
    def initialize(size: 5, policy:, cache:)
      @size = size
      @policy = policy
      @cache = cache
      @connections = []
      @mutex = Mutex.new
      @available = ConditionVariable.new
    end

    def acquire(target_spn)
      raise "SPN not permitted by policy" unless @policy.spn_permitted?(target_spn)

      conn = nil
      @mutex.synchronize do
        while @connections.length >= @size
          @available.wait(@mutex, 5)
        end
        conn = create_authenticated_connection(target_spn)
        @connections << conn
      end
      conn
    end

    def release(conn)
      @mutex.synchronize do
        @connections.delete(conn)
        @available.signal
      end
    end

    private

    def create_authenticated_connection(spn)
      flags = @policy.delegation_flags_for(spn)
      ticket = obtain_service_ticket(spn, flags)
      @cache.store(spn, ticket[:token], flags)
      { spn: spn, ticket: ticket, flags: flags, created: Time.now.to_i }
    end

    def obtain_service_ticket(spn, flags)
      # Simulate KRB5 ticket acquisition with delegation flags
      token_data = {
        'spn' => spn,
        'delegation_type' => resolve_delegation_type(flags),
        'forwardable' => (flags & DELEGATION_ALLOWED) != 0,
        'timestamp' => Time.now.to_i
      }
      { token: Base64.strict_encode64(JSON.generate(token_data)), flags: flags }
    end

    def resolve_delegation_type(flags)
      # Priority resolution: check unconstrained first
      if (flags & DELEGATION_ALLOWED) != 0
        'unconstrained'
      elsif (flags & DELEGATION_CONSTRAINED) != 0
        'constrained'
      elsif (flags & DELEGATION_RBCD) != 0
        'rbcd'
      else
        'none'
      end
    end
  end

  class CLI
    def initialize(config_path)
      config = load_config(config_path)
      @cache = TicketCache.new
      @policy = DelegationPolicy.new(config)
      @pool = ConnectionPool.new(size: config.fetch('pool_size', 5), policy: @policy, cache: @cache)
    end

    def connect(spn)
      conn = @pool.acquire(spn)
      puts "Connected to #{spn} with delegation: #{decode_delegation(conn[:flags])}"
      conn
    rescue => e
      $stderr.puts "Connection failed: #{e.message}"
      nil
    end

    def disconnect(conn)
      @pool.release(conn) if conn
    end

    def inspect_ticket(spn)
      entry = @cache.fetch(spn)
      return nil unless entry
      decoded = JSON.parse(Base64.strict_decode64(entry[:ticket]))
      puts "Ticket for #{spn}:"
      puts "  Delegation: #{decoded['delegation_type']}"
      puts "  Forwardable: #{decoded['forwardable']}"
      puts "  Flags: 0x#{entry[:flags].to_s(16).rjust(2, '0')}"
      decoded
    end

    private

    def load_config(path)
      JSON.parse(File.read(path))
    rescue Errno::ENOENT
      { 'delegation_mode' => 'constrained', 'pool_size' => 5, 'allowed_spns' => [] }
    end

    def decode_delegation(flags)
      parts = []
      parts << 'unconstrained' if (flags & DELEGATION_ALLOWED) != 0
      parts << 'constrained' if (flags & DELEGATION_CONSTRAINED) != 0
      parts << 'rbcd' if (flags & DELEGATION_RBCD) != 0
      parts.empty? ? 'none' : parts.join('+')
    end
  end
end

if __FILE__ == $0
  config_path = ARGV[0] || 'krb_pool.json'
  target_spn = ARGV[1] || 'HTTP/backend.corp.local'

  cli = KrbPool::CLI.new(config_path)
  conn = cli.connect(target_spn)
  cli.inspect_ticket(target_spn) if conn
  cli.disconnect(conn)
end
